// ════════════════════════════════════════════════════════════════════
//  WORKFLOW CONFIGURATION  –  edit ONLY the CONFIG block below.
//  Every other node reads its settings from this node's output.
// ════════════════════════════════════════════════════════════════════
const CONFIG = {
  // ── WordPress ──────────────────────────────────────────────────────
  sourceLanguage: 'it',          // language the articles are written in (Google Translate code)
  lookbackDays: 30,              // only posts PUBLISHED in the last N days are scanned

  // ── Google Sheets processing queue ─────────────────────────────────
  googleSheetId: 'YOUR_GOOGLE_SHEET_ID',   // the ID in the spreadsheet URL
  queueSheetName: 'Queue',                 // tab name (header row required, see README)

  // ── Batch, retry and concurrency ───────────────────────────────────
  maxJobsPerRun: 12,             // max article-language jobs per execution
  maxAttempts: 3,                // max attempts per article + language + content version
  retryCooldownMinutes: 60,      // minimum wait before a failed job is retried
  lockTimeoutMinutes: 240,       // a run lock older than this is considered abandoned
  fingerprintSalt: 'v2',         // change this value to force regeneration of ALL audio
  translationChunkChars: 4500,   // max characters sent to Google Translate per request

  // ── Google Cloud Run (TTS) and Cloud Storage ───────────────────────
  cloudRunTtsUrl: 'https://YOUR_CLOUD_RUN_URL/long-tts',
  gcsBucketName: 'YOUR_BUCKET_NAME',       // bucket used by your Cloud Run service
  audioPublicBaseUrl: '',                  // empty = https://storage.googleapis.com/<gcsBucketName>
  audioMimeType: 'audio/wav',
  minAudioBytes: 1024,                     // smaller files are treated as broken
  // Tokens: {postId} {lang} {langCode} {version}. {postId}, {lang} and {version} are required.
  defaultFilenamePattern: '{postId}-{lang}-{version}.wav',

  // ── Languages (one processing pipeline for all of them) ────────────
  // To add a language: copy an entry, set enabled:true, fill in the fields.
  //   key             short id used in filenames, queue keys and page markers (a-z, 0-9, -)
  //   languageCode    Google Cloud TTS language code
  //   voice           Google Cloud TTS voice name
  //   translateTo     Google Translate target code (default: first part of languageCode)
  //   wordpressPageId ID of the WordPress page that receives this language's players
  //   dateLocale      locale used to format the date shown in the player
  //   labels          texts shown in the player
  //   filenamePattern optional per-language override of defaultFilenamePattern
  languages: [
    {
      key: 'it', enabled: true,
      languageCode: 'it-IT', voice: 'it-IT-Neural2-F', translateTo: 'it',
      wordpressPageId: 1172, dateLocale: 'it-IT',
      labels: { voiceOver: 'VoiceOver', date: 'Data', readArticle: 'Leggi l’articolo' },
    },
    {
      key: 'en', enabled: true,
      languageCode: 'en-US', voice: 'en-US-Neural2-D', translateTo: 'en',
      wordpressPageId: 1523, dateLocale: 'en-US',
      labels: { voiceOver: 'VoiceOver', date: 'Date', readArticle: 'Read the article' },
    },
    {
      key: 'es', enabled: false,   // example – set enabled:true and a real page ID to activate
      languageCode: 'es-ES', voice: 'es-ES-Neural2-A', translateTo: 'es',
      wordpressPageId: 0, dateLocale: 'es-ES',
      labels: { voiceOver: 'VoiceOver', date: 'Fecha', readArticle: 'Leer el artículo' },
    },
  ],
};

// ───────────────────── validation (do not edit below) ─────────────────────
const problems = [];
const isPlaceholder = (v) => typeof v === 'string' && v.includes('YOUR_');
for (const k of ['googleSheetId', 'queueSheetName', 'cloudRunTtsUrl', 'gcsBucketName']) {
  if (!CONFIG[k] || isPlaceholder(CONFIG[k])) problems.push(`Set "${k}" in the Workflow Configuration node (still empty or a placeholder).`);
}
for (const k of ['maxJobsPerRun', 'maxAttempts', 'retryCooldownMinutes', 'lockTimeoutMinutes', 'translationChunkChars', 'lookbackDays']) {
  if (!Number.isFinite(Number(CONFIG[k])) || Number(CONFIG[k]) <= 0) problems.push(`"${k}" must be a positive number.`);
}
const pattern = CONFIG.defaultFilenamePattern;
const checkPattern = (p, where) => {
  for (const t of ['{postId}', '{lang}', '{version}']) {
    if (typeof p !== 'string' || !p.includes(t)) problems.push(`Filename pattern of ${where} must contain ${t}.`);
  }
};
checkPattern(pattern, 'defaultFilenamePattern');

const norm = (s) => String(s || '').trim().toLowerCase();
const seen = new Set();
const languages = [];
for (const l of CONFIG.languages) {
  if (l.enabled === false) continue;
  const key = norm(l.key);
  if (!/^[a-z0-9-]+$/.test(key)) { problems.push(`Language key "${l.key}" may only contain a-z, 0-9 and "-".`); continue; }
  if (seen.has(key)) problems.push(`Duplicate language key "${key}".`);
  seen.add(key);
  for (const f of ['languageCode', 'voice', 'wordpressPageId']) {
    if (!l[f]) problems.push(`Language "${key}": "${f}" is required.`);
  }
  const translateTo = norm(l.translateTo || String(l.languageCode || '').split('-')[0]);
  const filenamePattern = l.filenamePattern || pattern;
  if (l.filenamePattern) checkPattern(filenamePattern, `language "${key}"`);
  languages.push({
    key,
    languageCode: l.languageCode,
    voice: l.voice,
    translateTo,
    needsTranslation: translateTo !== norm(CONFIG.sourceLanguage),
    pageId: String(l.wordpressPageId),
    dateLocale: l.dateLocale || l.languageCode,
    filenamePattern,
    labels: { voiceOver: 'VoiceOver', date: 'Date', readArticle: 'Read the article', ...(l.labels || {}) },
  });
}
if (languages.length === 0) problems.push('Enable at least one language.');
if (problems.length) throw new Error('Configuration problem(s):\n- ' + problems.join('\n- '));

const base = String(CONFIG.audioPublicBaseUrl || `https://storage.googleapis.com/${CONFIG.gcsBucketName}`).replace(/\/+$/, '');

return [{
  json: {
    ...CONFIG,
    maxJobsPerRun: Math.floor(Number(CONFIG.maxJobsPerRun)),
    maxAttempts: Math.floor(Number(CONFIG.maxAttempts)),
    retryCooldownMinutes: Number(CONFIG.retryCooldownMinutes),
    lockTimeoutMinutes: Number(CONFIG.lockTimeoutMinutes),
    lookbackDays: Number(CONFIG.lookbackDays),
    translationChunkChars: Math.floor(Number(CONFIG.translationChunkChars)),
    minAudioBytes: Number(CONFIG.minAudioBytes),
    audioPublicBaseUrl: base,
    languages,
    lockKey: '__RUN_LOCK__',
  },
}];

// Extract readable text from every fetched post and build a content fingerprint.
// NOTE: htmlToText() is duplicated in "Build Speech Text" - keep both copies identical.
const cfg = $('Workflow Configuration').first().json;

const NAMED = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', hellip: '…', rsquo: '’', lsquo: '‘', rdquo: '”', ldquo: '“', ndash: '–', mdash: '—', laquo: '«', raquo: '»', euro: '€', agrave: 'à', egrave: 'è', eacute: 'é', igrave: 'ì', ograve: 'ò', ugrave: 'ù', Agrave: 'À', Egrave: 'È', Eacute: 'É', Igrave: 'Ì', Ograve: 'Ò', Ugrave: 'Ù', ccedil: 'ç', ntilde: 'ñ', uuml: 'ü', ouml: 'ö', auml: 'ä', szlig: 'ß' };
const cp = (n) => { try { return String.fromCodePoint(n); } catch (e) { return ' '; } };
function decodeEntities(s) {
  return s
    .replace(/&#x([0-9a-f]+);/gi, (_, h) => cp(parseInt(h, 16)))
    .replace(/&#(\d+);/g, (_, d) => cp(parseInt(d, 10)))
    .replace(/&([a-zA-Z][a-zA-Z0-9]*);/g, (m, n) => (NAMED[n] !== undefined ? NAMED[n] : m));
}
function htmlToText(html) {
  const h = decodeEntities(
    String(html == null ? '' : html)
      .replace(/<!--[\s\S]*?-->/g, ' ')
      .replace(/<(script|style|noscript)[^>]*>[\s\S]*?<\/\1>/gi, ' ')
      .replace(/<br\s*\/?>/gi, '\u0001')
      .replace(/<\/(p|li|h[1-6]|div|blockquote|figcaption|tr)>/gi, '\u0001')
      .replace(/<[^>]+>/g, ' ')
  );
  return h.split('\u0001')
    .map((s) => s.replace(/\s+/g, ' ').trim())
    .filter(Boolean)
    .map((s) => (/[.!?…:;]["'”’)»]?$/.test(s) ? s : s + '.'))
    .join(' ');
}
function plain(html) {
  return decodeEntities(String(html == null ? '' : html).replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim();
}

// Dependency-free SHA-256 (the Code node cannot always require('crypto')).
function utf8Bytes(str) {
  const out = [];
  for (const ch of str) {
    const c = ch.codePointAt(0);
    if (c < 0x80) out.push(c);
    else if (c < 0x800) out.push(0xc0 | (c >> 6), 0x80 | (c & 63));
    else if (c < 0x10000) out.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
    else out.push(0xf0 | (c >> 18), 0x80 | ((c >> 12) & 63), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
  }
  return out;
}
function sha256Hex(message) {
  const K = [0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5, 0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174, 0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da, 0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967, 0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85, 0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070, 0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3, 0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2];
  const bytes = utf8Bytes(message);
  const bitLen = bytes.length * 8;
  bytes.push(0x80);
  while (bytes.length % 64 !== 56) bytes.push(0);
  const hi = Math.floor(bitLen / 0x100000000), lo = bitLen >>> 0;
  for (const v of [hi, lo]) bytes.push((v >>> 24) & 255, (v >>> 16) & 255, (v >>> 8) & 255, v & 255);
  const H = [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19];
  const rotr = (x, n) => (x >>> n) | (x << (32 - n));
  const w = new Array(64);
  for (let off = 0; off < bytes.length; off += 64) {
    for (let i = 0; i < 16; i++) w[i] = ((bytes[off + i * 4] << 24) | (bytes[off + i * 4 + 1] << 16) | (bytes[off + i * 4 + 2] << 8) | bytes[off + i * 4 + 3]) >>> 0;
    for (let i = 16; i < 64; i++) {
      const s0 = rotr(w[i - 15], 7) ^ rotr(w[i - 15], 18) ^ (w[i - 15] >>> 3);
      const s1 = rotr(w[i - 2], 17) ^ rotr(w[i - 2], 19) ^ (w[i - 2] >>> 10);
      w[i] = (w[i - 16] + s0 + w[i - 7] + s1) >>> 0;
    }
    let [a, b, c, d, e, f, g, h] = H;
    for (let i = 0; i < 64; i++) {
      const S1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
      const ch = (e & f) ^ (~e & g);
      const t1 = (h + S1 + ch + K[i] + w[i]) >>> 0;
      const S0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const t2 = (S0 + maj) >>> 0;
      h = g; g = f; f = e; e = (d + t1) >>> 0; d = c; c = b; b = a; a = (t1 + t2) >>> 0;
    }
    H[0] = (H[0] + a) >>> 0; H[1] = (H[1] + b) >>> 0; H[2] = (H[2] + c) >>> 0; H[3] = (H[3] + d) >>> 0;
    H[4] = (H[4] + e) >>> 0; H[5] = (H[5] + f) >>> 0; H[6] = (H[6] + g) >>> 0; H[7] = (H[7] + h) >>> 0;
  }
  return H.map((v) => v.toString(16).padStart(8, '0')).join('');
}

const entries = $input.all()
  .map((it, idx) => ({ p: it.json, idx }))
  .filter(({ p }) => p && p.id !== undefined && p.id !== null && p.id !== '');
if (entries.length === 0) {
  // Keep one item flowing so the queue is still processed (retries) on days without new posts.
  return [{ json: { _noPosts: true } }];
}
return entries.map(({ p, idx }) => {
  const title = plain(p.title && p.title.rendered);
  const text = htmlToText(p.content && p.content.rendered);
  return {
    json: {
      postId: String(p.id),
      title,
      link: p.link || '',
      date: p.date_gmt || p.date || '',
      modified: p.modified_gmt || p.modified || '',
      hasText: text.length > 0,
      textLength: text.length,
      fingerprint: sha256Hex(`${cfg.fingerprintSalt}\n${title}\n${text}`),
    },
    pairedItem: { item: idx },
  };
});

// Compare WordPress posts with the queue and decide which queue rows must be created or reset.
const cfg = $('Workflow Configuration').first().json;
const LOCK = cfg.lockKey;
const nowMs = Date.now();
const nowIso = new Date(nowMs).toISOString();

const rows = $input.all().map((i) => i.json).filter((r) => r && r.JobKey);
const posts = $('Extract Text & Fingerprint').all().map((i) => i.json).filter((p) => p && p.postId);

// ── Run lock: another execution is (probably) still working → touch nothing ──
const lockRow = rows.find((r) => r.JobKey === LOCK);
const lockAgeMs = lockRow ? nowMs - Date.parse(lockRow.LastAttemptAt) : Infinity;
const locked = !!lockRow && String(lockRow.Status).trim().toLowerCase() === 'processing' && lockAgeMs < cfg.lockTimeoutMinutes * 60000;
if (locked) {
  return [{ json: { _upsert: false, _reason: 'locked', message: `Another run holds the lock (${Math.round(lockAgeMs / 60000)} min old). Nothing was changed.` } }];
}

const COLS = ['JobKey', 'PostID', 'Language', 'Title', 'Link', 'Date', 'Modified', 'Fingerprint', 'Status', 'Attempts', 'LastAttemptAt', 'CompletedAt', 'AudioFile', 'AudioUrl', 'Error'];
const rowOut = (o, reason) => {
  const r = {};
  for (const c of COLS) r[c] = o[c] === undefined || o[c] === null ? '' : o[c];
  r.Attempts = Number(o.Attempts) || 0;
  return { json: { _upsert: true, _reason: reason, ...r } };
};

const byKey = new Map(rows.map((r) => [r.JobKey, r]));
const out = new Map();
const stats = { newJobs: 0, contentChanged: 0, linkChanged: 0, recovered: 0, unchanged: 0, unreadable: 0 };

// ── 1. Orphaned "processing" rows (no live lock → the previous run died) ──
for (const r of rows) {
  if (r.JobKey === LOCK) continue;
  if (String(r.Status).trim().toLowerCase() === 'processing') {
    out.set(r.JobKey, rowOut({ ...r, Status: 'failed', Error: 'Interrupted: the previous run ended before this job finished.' }, 'recovered'));
    stats.recovered++;
  }
}

// ── 2. New and changed articles, for every enabled language ──
for (const p of posts) {
  for (const lang of cfg.languages) {
    const key = `${p.postId}:${lang.key}`;
    const existing = byKey.get(key);
    let reason = null;
    if (!existing) reason = 'new';
    else if (String(existing.Fingerprint) !== p.fingerprint) reason = 'content-changed';
    else if (existing.Link && p.link && String(existing.Link) !== p.link) reason = 'link-changed';
    if (!reason) { stats.unchanged++; continue; }

    const base = {
      JobKey: key, PostID: p.postId, Language: lang.key, Title: p.title, Link: p.link,
      Date: p.date, Modified: p.modified, Fingerprint: p.fingerprint,
    };
    if (p.hasText) {
      // Status "pending" + Attempts 0 = the retry counter is reset for the new version.
      out.set(key, rowOut({ ...base, Status: 'pending', Attempts: 0, LastAttemptAt: '', CompletedAt: '', AudioFile: '', AudioUrl: '', Error: '' }, reason));
    } else {
      stats.unreadable++;
      out.set(key, rowOut({ ...base, Status: 'failed', Attempts: cfg.maxAttempts, LastAttemptAt: nowIso, CompletedAt: '', AudioFile: '', AudioUrl: '', Error: 'The WordPress post has no readable text. It is retried automatically when the content changes.' }, reason));
    }
    if (reason === 'new') stats.newJobs++; else if (reason === 'content-changed') stats.contentChanged++; else stats.linkChanged++;
  }
}

if (out.size === 0) {
  return [{ json: { _upsert: false, _reason: 'no changes', stats, message: 'No new or changed articles.' } }];
}
return [...out.values()];

// Pick up to maxJobsPerRun jobs: pending first (oldest article first), then retryable failures.
const cfg = $('Workflow Configuration').first().json;
const LOCK = cfg.lockKey;
const nowMs = Date.now();

const rows = $input.all().map((i) => i.json).filter((r) => r && r.JobKey);

const lockRow = rows.find((r) => r.JobKey === LOCK);
const lockAgeMs = lockRow ? nowMs - Date.parse(lockRow.LastAttemptAt) : Infinity;
if (lockRow && String(lockRow.Status).trim().toLowerCase() === 'processing' && lockAgeMs < cfg.lockTimeoutMinutes * 60000) {
  return [{ json: { jobCount: 0, jobs: [], reason: 'locked', message: `Another run holds the lock (${Math.round(lockAgeMs / 60000)} min old).` } }];
}

const langByKey = new Map(cfg.languages.map((l) => [l.key, l]));
const cooldownMs = cfg.retryCooldownMinutes * 60000;
const stats = { pending: 0, retryable: 0, coolingDown: 0, exhausted: 0, done: 0, other: 0 };
const pending = [];
const retries = [];

for (const r of rows) {
  if (r.JobKey === LOCK) continue;
  const lang = langByKey.get(String(r.Language));
  if (!lang) continue; // disabled language or foreign row
  const status = String(r.Status === undefined || r.Status === null ? '' : r.Status).trim().toLowerCase();
  const attempts = Number(r.Attempts) || 0;
  if (status === '' || status === 'pending') { pending.push({ r, lang }); stats.pending++; }
  else if (status === 'failed') {
    if (attempts >= cfg.maxAttempts) { stats.exhausted++; continue; }
    const last = Date.parse(r.LastAttemptAt);
    if (Number.isFinite(last) && nowMs - last < cooldownMs) { stats.coolingDown++; continue; }
    retries.push({ r, lang }); stats.retryable++;
  } else if (status === 'done') stats.done++;
  else stats.other++;
}

const ts = (v) => { const t = Date.parse(v); return Number.isFinite(t) ? t : 0; };
pending.sort((a, b) => ts(a.r.Date) - ts(b.r.Date));
retries.sort((a, b) => ts(a.r.LastAttemptAt) - ts(b.r.LastAttemptAt));

const selected = [...pending, ...retries].slice(0, cfg.maxJobsPerRun);
const jobs = selected.map(({ r, lang }) => ({
  jobKey: r.JobKey,
  postId: String(r.PostID),
  lang: lang.key,
  title: r.Title || '',
  link: r.Link || '',
  date: r.Date || '',
  modified: r.Modified || '',
  fingerprint: String(r.Fingerprint || ''),
  attempts: Number(r.Attempts) || 0,
  previousStatus: String(r.Status || 'pending'),
  languageCode: lang.languageCode,
  voice: lang.voice,
  translateTo: lang.translateTo,
  needsTranslation: lang.needsTranslation,
  pageId: lang.pageId,
  dateLocale: lang.dateLocale,
  labels: lang.labels,
  filenamePattern: lang.filenamePattern,
  cloudRunTtsUrl: cfg.cloudRunTtsUrl,
  audioBaseUrl: cfg.audioPublicBaseUrl,
  audioMimeType: cfg.audioMimeType,
  minAudioBytes: cfg.minAudioBytes,
  translationChunkChars: cfg.translationChunkChars,
}));

return [{
  json: {
    jobCount: jobs.length,
    jobs,
    reason: jobs.length ? 'ok' : 'queue empty',
    message: jobs.length ? `${jobs.length} job(s) selected.` : 'No pending or retryable jobs.',
    stats,
  },
}];

// Turn the selected jobs back into one item per job for the Loop Over Jobs node.
const selection = $('Select Pending & Retryable Jobs').first().json;
return (selection.jobs || []).map((job) => ({ json: job, pairedItem: { item: 0 } }));

// First node inside the loop. Every later node can look the job up here with $('Prepare Job').item.
const j = $json;
for (const k of ['jobKey', 'postId', 'lang', 'languageCode', 'voice', 'pageId', 'cloudRunTtsUrl', 'audioBaseUrl', 'filenamePattern', 'fingerprint']) {
  if (!j[k]) throw new Error(`The queued job is missing "${k}". Check the queue row ${j.jobKey || ''}.`);
}
return { ...j, attempts: Number(j.attempts) || 0, startedAt: new Date().toISOString() };

// Combine the queued job with the freshly fetched article: text to speak, audio filename and URL.
// NOTE: htmlToText() is duplicated in "Extract Text & Fingerprint" - keep both copies identical.
const job = $('Prepare Job').item.json;
const post = $json;

const NAMED = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', hellip: '…', rsquo: '’', lsquo: '‘', rdquo: '”', ldquo: '“', ndash: '–', mdash: '—', laquo: '«', raquo: '»', euro: '€', agrave: 'à', egrave: 'è', eacute: 'é', igrave: 'ì', ograve: 'ò', ugrave: 'ù', Agrave: 'À', Egrave: 'È', Eacute: 'É', Igrave: 'Ì', Ograve: 'Ò', Ugrave: 'Ù', ccedil: 'ç', ntilde: 'ñ', uuml: 'ü', ouml: 'ö', auml: 'ä', szlig: 'ß' };
const cp = (n) => { try { return String.fromCodePoint(n); } catch (e) { return ' '; } };
function decodeEntities(s) {
  return s
    .replace(/&#x([0-9a-f]+);/gi, (_, h) => cp(parseInt(h, 16)))
    .replace(/&#(\d+);/g, (_, d) => cp(parseInt(d, 10)))
    .replace(/&([a-zA-Z][a-zA-Z0-9]*);/g, (m, n) => (NAMED[n] !== undefined ? NAMED[n] : m));
}
function htmlToText(html) {
  const h = decodeEntities(
    String(html == null ? '' : html)
      .replace(/<!--[\s\S]*?-->/g, ' ')
      .replace(/<(script|style|noscript)[^>]*>[\s\S]*?<\/\1>/gi, ' ')
      .replace(/<br\s*\/?>/gi, '\u0001')
      .replace(/<\/(p|li|h[1-6]|div|blockquote|figcaption|tr)>/gi, '\u0001')
      .replace(/<[^>]+>/g, ' ')
  );
  return h.split('\u0001')
    .map((s) => s.replace(/\s+/g, ' ').trim())
    .filter(Boolean)
    .map((s) => (/[.!?…:;]["'”’)»]?$/.test(s) ? s : s + '.'))
    .join(' ');
}
function plain(html) {
  return decodeEntities(String(html == null ? '' : html).replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim();
}

const title = plain(post.title && post.title.rendered) || job.title;
const text = htmlToText(post.content && post.content.rendered);
if (!text) throw new Error('The WordPress post has no readable text.');

// Deterministic, versioned filename: the version is the first 10 characters of the content fingerprint.
const version = String(job.fingerprint).slice(0, 10);
const audioFile = job.filenamePattern
  .split('{postId}').join(job.postId)
  .split('{lang}').join(job.lang)
  .split('{langCode}').join(job.languageCode)
  .split('{version}').join(version)
  .replace(/[^A-Za-z0-9._-]/g, '-');
const audioUrl = `${String(job.audioBaseUrl).replace(/\/+$/, '')}/${audioFile}`;

return {
  ...job,
  title,
  link: post.link || job.link,
  date: post.date_gmt || job.date,
  modified: post.modified_gmt || job.modified,
  version,
  audioFile,
  audioUrl,
  speechText: `${title}. ${text}`.replace(/\s+/g, ' ').trim(),
};

// Interpret the HEAD request that looks for an audio file already generated for this content version.
const job = $('Build Speech Text').item.json;
const status = Number($json.statusCode);
const rawLen = $json.headers ? $json.headers['content-length'] : undefined;
const len = rawLen === undefined || rawLen === '' ? NaN : Number(rawLen);
const exists = status >= 200 && status < 300 && (!Number.isFinite(len) || len >= job.minAudioBytes);
const audioCheck = `HTTP ${status}${Number.isFinite(len) ? `, ${len} bytes` : ''}`;
if (exists) {
  const { speechText, ...rest } = job; // the text is not needed any more
  return { ...rest, audioExists: true, audioCheck };
}
return { ...job, audioExists: false, audioCheck };

// Split the speech text into sentence-aligned chunks that fit one Google Translate request.
const job = $input.all()[0].json;
const max = Math.max(500, Number(job.translationChunkChars) || 4500);

function splitText(text, limit) {
  const sentences = String(text).split(/(?<=[.!?…])\s+/);
  const chunks = [];
  let cur = '';
  const flush = () => { if (cur.trim()) chunks.push(cur.trim()); cur = ''; };
  for (let s of sentences) {
    while (s.length > limit) {            // a single very long sentence: cut on whitespace
      let cut = s.lastIndexOf(' ', limit);
      if (cut < limit * 0.5) cut = limit;
      flush();
      chunks.push(s.slice(0, cut).trim());
      s = s.slice(cut).trim();
    }
    if (!s) continue;
    if (cur && (cur + ' ' + s).length > limit) flush();
    cur = cur ? cur + ' ' + s : s;
  }
  flush();
  return chunks;
}

const { speechText, ...jobLite } = job; // do not copy the full text into every chunk
const chunks = splitText(speechText, max);
if (chunks.length === 0) throw new Error('There is no text to translate.');
return chunks.map((chunkText, i) => ({
  json: { chunkIndex: i, chunkCount: chunks.length, chunkText, translateTo: job.translateTo, job: jobLite },
  pairedItem: { item: 0 },
}));

// Re-assemble the translated chunks. This node must NEVER throw: it receives N items, and a failing
// multi-item node could hand N items to the error path. A problem is returned as ONE item with
// "translationError"; the single-item node "Prepare TTS Request" raises it.
const items = $input.all();

const NAMED = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', hellip: '…', rsquo: '’', lsquo: '‘', rdquo: '”', ldquo: '“', ndash: '–', mdash: '—' };
const cp = (n) => { try { return String.fromCodePoint(n); } catch (e) { return ' '; } };
// Google Translate returns HTML-escaped text (e.g. &#39;) - decode it so the voice does not read entities aloud.
const decode = (s) => s
  .replace(/&#x([0-9a-f]+);/gi, (_, h) => cp(parseInt(h, 16)))
  .replace(/&#(\d+);/g, (_, d) => cp(parseInt(d, 10)))
  .replace(/&([a-zA-Z][a-zA-Z0-9]*);/g, (m, n) => (NAMED[n] !== undefined ? NAMED[n] : m));

let ctx = null;
try { ctx = $('Split Text into Chunks').itemMatching(0).json.job; } catch (e) { ctx = null; }
if (!ctx) { const withJob = items.find((it) => it.json && it.json.job); ctx = withJob ? withJob.json.job : null; }

let problem = '';
if (!ctx) {
  problem = 'Internal error: the job context was lost during translation.';
} else {
  const missing = [];
  let firstError = '';
  items.forEach((it, i) => {
    const t = it.json ? it.json.translatedText : undefined;
    if (typeof t !== 'string' || t.trim() === '') {
      missing.push(i + 1);
      const e = it.json ? it.json.error : undefined;
      if (!firstError && e) firstError = String(typeof e === 'string' ? e : (e.message || JSON.stringify(e))).slice(0, 200);
    }
  });
  if (missing.length) problem = `Google Translate returned no text for chunk(s) ${missing.join(', ')} of ${items.length}${firstError ? ': ' + firstError : ''}.`;
}

if (problem) {
  return [{ json: { ...(ctx || {}), translationError: problem }, pairedItem: { item: 0 } }];
}
const speechText = items.map((it) => decode(it.json.translatedText)).join(' ').replace(/\s+/g, ' ').trim();
return [{ json: { ...ctx, speechText, translatedChunks: items.length }, pairedItem: { item: 0 } }];

// Build the request for the existing Cloud Run service. Only the documented fields are sent.
const { speechText, translationError, ...job } = $json;
if (translationError) throw new Error(translationError);
const text = String(speechText || '').replace(/\s+/g, ' ').trim();
if (!text) throw new Error('The text to synthesize is empty.');
return {
  ...job,
  ttsRequest: { text, language: job.languageCode, voice: job.voice, filename: job.audioFile },
};

// Two ways in:
//  A) "Audio Already Exists?" (true)  -> $json is the job (audioExists = true), nothing to verify again.
//  B) "Verify Generated Audio"        -> $json is the HEAD response of the freshly generated file.
if ($json.audioExists === true && $json.jobKey) {
  const { audioExists, audioCheck, ...job } = $json;
  return { ...job, audioSource: 'existing' };
}
const { ttsRequest, ...job } = $('Prepare TTS Request').item.json;
const status = Number($json.statusCode);
const rawLen = $json.headers ? $json.headers['content-length'] : undefined;
const len = rawLen === undefined || rawLen === '' ? NaN : Number(rawLen);
if (!(status >= 200 && status < 300)) {
  throw new Error(`The generated audio is not accessible at ${job.audioUrl} (HTTP ${status || 'no response'}). Check the Cloud Storage bucket and its public access.`);
}
if (Number.isFinite(len) && len < job.minAudioBytes) {
  throw new Error(`The generated audio file is too small (${len} bytes, minimum ${job.minAudioBytes}): ${job.audioUrl}`);
}
return { ...job, audioSource: 'generated' };

// Replace (or append) this article's player block and keep everything else on the page untouched.
const job = $('Confirm Audio Ready').item.json;
const page = $json;

const raw = page.content && page.content.raw;
if (typeof raw !== 'string') {
  throw new Error(`WordPress page ${job.pageId} returned no "content.raw". The API user needs permission to edit this page (context=edit). The page was NOT modified.`);
}

const esc = (s) => String(s === undefined || s === null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const labels = { voiceOver: 'VoiceOver', date: 'Date', readArticle: 'Read the article', ...(job.labels || {}) };

function formatDate(d, locale) {
  if (!d) return '';
  const s = String(d);
  const iso = /(Z|[+-]\d\d:?\d\d)$/i.test(s) || !/T/.test(s) ? s : s + 'Z';
  const dt = new Date(iso);
  if (isNaN(dt.getTime())) return s;
  try { return dt.toLocaleDateString(locale || 'en-US', { year: 'numeric', month: 'long', day: 'numeric', timeZone: 'UTC' }); }
  catch (e) { return dt.toISOString().slice(0, 10); }
}

const id = String(job.postId);
const lang = String(job.lang);
const tag = `${id}:${lang}`;
const block = [
  `<!-- wp-voiceover:start:${tag} -->`,
  `<div class="wp-voiceover" data-voiceover-post="${esc(id)}" data-voiceover-lang="${esc(lang)}" data-voiceover-version="${esc(job.version)}">`,
  `<p>🎧 ${esc(labels.voiceOver)}: ${esc(job.title)}</p>`,
  `<p>${esc(labels.date)}: ${esc(formatDate(job.date, job.dateLocale))}</p>`,
  `<p><a href="${esc(job.link)}">${esc(labels.readArticle)}</a></p>`,
  `<audio controls preload="none"><source src="${esc(job.audioUrl)}" type="${esc(job.audioMimeType)}"></audio>`,
  `</div>`,
  `<!-- wp-voiceover:end:${tag} -->`,
].join('\n');

const rx = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
// The tempered pattern never runs across another voiceover marker, so a damaged block cannot swallow other players.
const currentRe = new RegExp(`<!-- wp-voiceover:start:${rx(tag)} -->(?:(?!<!-- wp-voiceover:start:)[\\s\\S])*?<!-- wp-voiceover:end:${rx(tag)} -->`, 'g');
const legacyRe = new RegExp(`<!-- wp-voiceover:${rx(tag)} -->(?:(?!<!-- wp-voiceover:)[\\s\\S])*?</audio>`, 'g'); // v1.x blocks

let replaced = 0;
let content = raw.replace(currentRe, () => (replaced++ === 0 ? block : ''));      // 1st match replaced, duplicates removed
content = content.replace(legacyRe, () => (replaced++ === 0 ? block : ''));
if (replaced === 0) content = (raw.trim() ? raw.replace(/\s+$/, '') + '\n\n' : '') + block + '\n';

return { ...job, newPageContent: content, playerAction: replaced === 0 ? 'appended' : (replaced > 1 ? 'replaced-and-deduplicated' : 'replaced') };

// WordPress can answer 200 and still strip the <audio> tag (HTML filtering). Verify the saved content.
const { newPageContent, ...job } = $('Build Updated Page Content').item.json;
const page = $json;
const raw = page.content && page.content.raw;
const rendered = page.content && page.content.rendered;
const savedRaw = typeof raw === 'string';
const present = (savedRaw && raw.includes(job.audioFile)) || (typeof rendered === 'string' && rendered.includes(job.audioFile));
if (!present) {
  throw new Error(`WordPress accepted the update of page ${job.pageId} but the audio player is not in the saved content. The API user probably lacks the "unfiltered_html" capability, so <audio> was stripped.`);
}
if (savedRaw && !raw.includes(`<!-- wp-voiceover:start:${job.postId}:${job.lang} -->`)) {
  throw new Error(`WordPress saved page ${job.pageId} without the voiceover marker for ${job.postId}:${job.lang}.`);
}
return { ...job, publishedAt: new Date().toISOString() };

// Derive the article-level status (done / partial / failed / pending / processing) for every post.
const cfg = $('Workflow Configuration').first().json;
const LOCK = cfg.lockKey;
const enabled = new Set(cfg.languages.map((l) => l.key));
const rows = $input.all().map((i) => i.json).filter((r) => r && r.JobKey && r.JobKey !== LOCK && enabled.has(String(r.Language)));

const groups = new Map();
for (const r of rows) {
  const id = String(r.PostID);
  if (!groups.has(id)) groups.set(id, []);
  groups.get(id).push(r);
}
const norm = (s) => { const v = String(s === undefined || s === null ? '' : s).trim().toLowerCase(); return v === '' ? 'pending' : v; };

const updates = [];
for (const list of groups.values()) {
  const st = list.map((r) => norm(r.Status));
  const done = st.filter((s) => s === 'done').length;
  let article;
  if (st.includes('processing')) article = 'processing';
  else if (done === st.length) article = 'done';
  else if (done > 0) article = 'partial';
  else if (st.includes('failed')) article = 'failed';
  else article = 'pending';
  for (const r of list) {
    if (String(r.ArticleStatus === undefined || r.ArticleStatus === null ? '' : r.ArticleStatus) !== article) {
      updates.push({ json: { JobKey: r.JobKey, ArticleStatus: article } });
    }
  }
}
return updates; // empty array = nothing to write

// Turn whatever reached the error bus into ONE queue update. Runs in "all items" mode on purpose:
// no matter how many error items arrive, exactly one item goes back to the loop. Must never throw.
function messageOf(e) {
  if (e === undefined || e === null) return 'Unknown error';
  if (typeof e === 'string') return e;
  const parts = [];
  if (e.message) parts.push(String(e.message));
  if (e.description && e.description !== e.message) parts.push(String(e.description));
  if (e.httpCode) parts.push(`HTTP ${e.httpCode}`);
  if (parts.length) return parts.join(' - ');
  try { return JSON.stringify(e).slice(0, 300); } catch (x) { return 'Unknown error'; }
}

const items = $input.all();
const first = items[0] ? items[0].json || {} : {};

// Identify the job ONLY through item linking (or the item itself). There is deliberately no
// "latest run" fallback: guessing could write the failure onto a different article's row.
let job = null;
try { job = $('Prepare Job').itemMatching(0).json; } catch (e1) { job = null; }
if (!job && first.jobKey) job = first;

let err = first.error;
if (err === undefined && first.message) err = first.message;
const step = err && typeof err === 'object' && err.node && err.node.name ? `[${err.node.name}] ` : '';
const message = (step + messageOf(err)).replace(/\s+/g, ' ').slice(0, 500);

return [{
  json: {
    jobKey: job ? job.jobKey : '__UNMATCHED_ERROR__',
    attempts: job ? (Number(job.attempts) || 0) + 1 : 0,
    lastAttemptAt: new Date().toISOString(),
    errorMessage: job ? message : `Could not identify the failing job. ${message}`,
  },
  pairedItem: { item: 0 },
}];
